<?php
require_once '../config/auth.php'; require_once '../config/database.php';
if (($_SESSION['staff_role'] ?? '') !== 'master') { http_response_code(403); exit('Acesso restrito ao Staff Master.'); }
$search=trim((string)($_GET['q']??''));$category=trim((string)($_GET['category']??''));$action=trim((string)($_GET['action']??''));$staffId=(int)($_GET['staff_id']??0);$userId=(int)($_GET['user_id']??0);$start=trim((string)($_GET['start']??''));$end=trim((string)($_GET['end']??''));
$where=[];$params=[];if($search!==''){ $where[]='(a.affected_user_name LIKE ? OR a.staff_name LIKE ? OR a.details LIKE ? OR a.action LIKE ?)';$t='%'.$search.'%';array_push($params,$t,$t,$t,$t);}if($category!==''){$where[]='a.category=?';$params[]=$category;}if($action!==''){$where[]='a.action=?';$params[]=$action;}if($staffId>0){$where[]='a.staff_id=?';$params[]=$staffId;}if($userId>0){$where[]='a.affected_user_id=?';$params[]=$userId;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)){$where[]='a.created_at>=?';$params[]=$start.' 00:00:00';}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$end)){$where[]='a.created_at<=?';$params[]=$end.' 23:59:59';}$w=$where?'WHERE '.implode(' AND ',$where):'';$q=$pdo->prepare("SELECT * FROM audit_logs a $w ORDER BY a.created_at DESC,a.id DESC LIMIT 5000");$q->execute($params);$rows=$q->fetchAll();
function x($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
header('Content-Type: application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition: attachment; filename="morningfall_logs_'.date('Y-m-d_H-i-s').'.xls"');
echo "\xEF\xBB\xBF<table border='1'><tr><th>ID</th><th>Data/Hora</th><th>Staff</th><th>ID Staff</th><th>Usuário afetado</th><th>ID Usuário</th><th>Ação</th><th>Categoria</th><th>Alteração</th><th>Antes</th><th>Depois</th></tr>";foreach($rows as $r){echo '<tr><td>'.x($r['id']).'</td><td>'.x($r['created_at']).'</td><td>'.x($r['staff_name']).'</td><td>'.x($r['staff_id']).'</td><td>'.x($r['affected_user_name']).'</td><td>'.x($r['affected_user_id']).'</td><td>'.x($r['action']).'</td><td>'.x($r['category']).'</td><td>'.x($r['details']).'</td><td>'.x($r['before_data']).'</td><td>'.x($r['after_data']).'</td></tr>'; } echo '</table>';
